import jax
import jax.numpy as jnp
import numpy as np
from pathlib import Path
from src.rsa_open.fit import TheoryModel
from src.rsa.loop.novelty import plain_pool
from src.rsa.context import group_by_shape

cand_path = Path('/scratch/users/mcfrank/auto-psych/agent_trees/34f4248e29dbad0a/repo/_runs/chain_0/experiment1/loop/round_2/candidate_5_repair_1/candidate.py')
cand = TheoryModel(cand_path, name="candidate")

pool = plain_pool()
pool_groups = list(group_by_shape(pool).values())

cand_params = {"alpha": jnp.array(3.0), "w_singleton": jnp.array(0.8), "w_features": jnp.array(0.3)}

cand_preds = []
for g in pool_groups:
    p_l = cand.group_probs(cand_params, g)
    p_s = cand.group_speaker(cand_params, g)
    cand_preds.append(np.concatenate([np.asarray(p_l).ravel(), np.asarray(p_s).ravel()]))
cand_vec = np.concatenate(cand_preds)

models_dir = Path('/scratch/users/mcfrank/auto-psych/agent_trees/34f4248e29dbad0a/repo/_runs/chain_0/experiment1/loop/models')
print("Checking novelty distance against all 13 models in loop/models:")
key = jax.random.PRNGKey(42)
min_rmse = 999.0
closest_name = ""

for p in sorted(models_dir.glob('*.py')):
    m = TheoryModel(p)
    if p.stem == 'contextual_contrast_listener':
        m_params = {"alpha": jnp.array(3.0), "w_singleton": jnp.array(0.8)}
    elif p.stem == 'contextual_contrast_distinct_listener':
        m_params = {"alpha": jnp.array(3.0), "w_singleton": jnp.array(0.8), "w_distinct": jnp.array(0.3)}
    elif p.stem == 'contextual_isolation_listener':
        m_params = {"alpha": jnp.array(3.0), "w_isolation": jnp.array(0.8)}
    elif p.stem == 'attentional_bottleneck_listener':
        m_params = {"alpha": jnp.array(3.0), "w_isolation": jnp.array(0.8)}
    elif p.stem == 'rsa_l2_singleton_feat_color_valence_l0':
        m_params = {"alpha": jnp.array(3.0), "w_singleton": jnp.array(0.8), "w_distinct": jnp.array(0.3),
                    "w_features": jnp.array(0.3), "w_valence": jnp.array(0.0), "w_color": jnp.array(0.0)}
    else:
        m_params = {k: v.sample(key) for k, v in m.params.items()}

    m_preds = []
    for g in pool_groups:
        p_l = m.group_probs(m_params, g)
        p_s = m.group_speaker(m_params, g)
        m_preds.append(np.concatenate([np.asarray(p_l).ravel(), np.asarray(p_s).ravel()]))
    m_vec = np.concatenate(m_preds)

    rmse = float(np.sqrt(np.mean((cand_vec - m_vec) ** 2)))
    print(f"  vs {p.stem:40s}: RMSE = {rmse:.5f}")
    if rmse < min_rmse:
        min_rmse = rmse
        closest_name = p.stem

print(f"\nMinimum RMSE: {min_rmse:.5f} (closest: {closest_name}) vs threshold 0.0020")
assert min_rmse >= 0.0020, f"FAILED NOVELTY: {min_rmse} < 0.0020"
print("SUCCESS: Novelty confirmed!")
